using System;
using UnityEditor;
using UnityEditor.Build;
using UnityEngine;
using UnityEngine.Rendering;

/// <summary>
/// Applies the Unity project settings required for the iOS build.
/// ProjectSettings.asset is generated by Unity on first open, so all values
/// that matter for the build are set here instead of being committed.
/// </summary>
public static class ArmorSimProjectSetup
{
    public static void Apply(string bundleId)
    {
        if (string.IsNullOrWhiteSpace(bundleId))
        {
            throw new ArgumentException(
                "ArmorSim bundle ID is empty. Pass -armorsimBundleId <id> or set IOS_BUNDLE_ID.",
                nameof(bundleId));
        }

        string applicationId = bundleId.Trim();

        PlayerSettings.companyName = "GalimovDynamics";
        PlayerSettings.productName = "ArmorSim";
        PlayerSettings.bundleVersion = "1.0.0";

        Guard("color space", () => PlayerSettings.colorSpace = ColorSpace.Linear);

        Guard("iOS build number", () => PlayerSettings.iOS.buildNumber = "1");
        Guard("application identifier", () => PlayerSettings.SetApplicationIdentifier(NamedBuildTarget.iOS, applicationId));
        Guard("scripting backend", () => PlayerSettings.SetScriptingBackend(NamedBuildTarget.iOS, ScriptingImplementation.IL2CPP));
        Guard("iOS architecture", () => PlayerSettings.SetArchitecture(NamedBuildTarget.iOS, 1));
        Guard("API compatibility level", () => PlayerSettings.SetApiCompatibilityLevel(NamedBuildTarget.iOS, ApiCompatibilityLevel.NET_Standard));
        Guard("IL2CPP compiler configuration", () => PlayerSettings.SetIl2CppCompilerConfiguration(NamedBuildTarget.iOS, Il2CppCompilerConfiguration.Release));
        Guard("managed stripping level", () => PlayerSettings.SetManagedStrippingLevel(NamedBuildTarget.iOS, ManagedStrippingLevel.Low));

        Guard("graphics APIs", () =>
        {
            PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.iOS, false);
            PlayerSettings.SetGraphicsAPIs(BuildTarget.iOS, new[] { GraphicsDeviceType.Metal });
        });

        Guard("iOS SDK version", () => PlayerSettings.iOS.sdkVersion = iOSSdkVersion.DeviceSDK);
        Guard("iOS target OS version", () => PlayerSettings.iOS.targetOSVersionString = "15.0");
        Guard("iOS target device", () => PlayerSettings.iOS.targetDevice = iOSTargetDevice.iPhoneAndiPad);
        Guard("iOS full screen requirement", () => PlayerSettings.iOS.requiresFullScreen = true);
        Guard("iOS automatic signing", () => PlayerSettings.iOS.appleEnableAutomaticSigning = false);

        Guard("interface orientation", () =>
        {
            PlayerSettings.defaultInterfaceOrientation = UIOrientation.LandscapeLeft;
            PlayerSettings.allowedAutorotateToPortrait = false;
            PlayerSettings.allowedAutorotateToPortraitUpsideDown = false;
            PlayerSettings.allowedAutorotateToLandscapeLeft = true;
            PlayerSettings.allowedAutorotateToLandscapeRight = true;
        });

        // Both old Input and InputSystem are used by the game.
        // 0 = Input Manager (Old), 1 = Input System (New), 2 = Both.
        try
        {
            var assets = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/ProjectSettings.asset");
            if (assets != null && assets.Length > 0)
            {
                var so = new SerializedObject(assets[0]);
                var property = so.FindProperty("activeInputHandler");
                if (property != null)
                {
                    property.intValue = 2;
                    so.ApplyModifiedPropertiesWithoutUndo();
                }
                else
                {
                    Debug.LogWarning("[ArmorSimProjectSetup] ProjectSettings.asset has no activeInputHandler property.");
                }
            }
            else
            {
                Debug.LogWarning("[ArmorSimProjectSetup] ProjectSettings.asset is not available yet; activeInputHandler was not set.");
            }
        }
        catch (Exception exception)
        {
            Debug.LogWarning($"[ArmorSimProjectSetup] Could not set activeInputHandler: {exception.Message}");
        }
    }

    private static void Guard(string what, Action action)
    {
        try
        {
            action();
        }
        catch (Exception exception)
        {
            Debug.LogWarning($"[ArmorSimProjectSetup] Could not apply {what}: {exception.Message}");
        }
    }
}
